package net.neoforged.neoforge.event.entity.player;import net.minecraft.world.entity.player.Player;public class PlayerEvent{private final Player entity;public PlayerEvent(Player p){entity=p;}public Player getEntity(){return entity;}public static class Clone extends PlayerEvent{private final Player old;private final boolean death;public Clone(Player o,Player n){this(o,n,true);}public Clone(Player o,Player n,boolean d){super(n);old=o;death=d;}public Player getOriginal(){return old;}public boolean isWasDeath(){return death;}}public static class PlayerLoggedInEvent extends PlayerEvent{public PlayerLoggedInEvent(Player p){super(p);}}}
